function toJson(list){
    json = "";
    for (i in list)
    {
        all = list[i].match(/(.*?)=(.*)/);
        key = all[1];
        value = all[2];
        json += '"' + key + '":' + '"' + value + '",'
    }
    json = '{' + String(json).replace(/,$/,'')+ '}'
    return json;
}
